<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireApprovedSeller();
$pdo=db(); $sellerId=(int)Auth::userId();
$stmt=$pdo->prepare("SELECT COALESCE(SUM(oi.subtotal),0) FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE oi.seller_id=? AND o.status IN ('paid','processing','shipped','completed') AND oi.fulfillment_status <> 'cancelled'");
$stmt->execute([$sellerId]); $gross=(float)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COUNT(*) FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE oi.seller_id=? AND o.status IN ('paid','processing','shipped','completed') AND oi.fulfillment_status <> 'cancelled'");
$stmt->execute([$sellerId]); $sales=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM withdrawals WHERE user_id=? AND status IN ('pending','approved','processing','paid')");
$stmt->execute([$sellerId]); $withdrawn=(float)$stmt->fetchColumn();
$available=max(0,$gross-$withdrawn);
$stmt=$pdo->prepare("SELECT o.order_number,oi.subtotal,oi.fulfillment_status,o.created_at FROM order_items oi INNER JOIN orders o ON o.id=oi.order_id WHERE oi.seller_id=? ORDER BY oi.id DESC LIMIT 8");
$stmt->execute([$sellerId]); $rows=$stmt->fetchAll();
function eb(string $s):string{return match($s){'completed'=>'success','shipped'=>'info','cancelled'=>'danger',default=>'warning'};}
?>
