<section class="grid grid-cols-1 gap-4 md:grid-cols-3"><article class="card p-5"><p class="muted">Gross sales</p><strong class="text-2xl text-slate-900">GH₵ <?=number_format($gross,2)?></strong><p class="muted mt-1">Eligible paid orders</p></article><article class="card p-5"><p class="muted">Sales items</p><strong class="text-2xl text-slate-900"><?=number_format($sales)?></strong><p class="muted mt-1">Your fulfilled order items</p></article><article class="card p-5"><p class="muted">Available balance</p><strong class="text-2xl text-slate-900">GH₵ <?=number_format($available,2)?></strong><p class="muted mt-1">After existing payout requests</p></article></section>
<section class="card mt-5 overflow-hidden"><div class="border-b border-slate-200 p-5"><h2 class="m-0">Recent sales</h2><p class="muted">The latest order items attributed to your seller account.</p></div><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Order</th><th>Amount</th><th>Fulfillment</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['order_number'])?></strong></td><td>GH₵ <?=number_format((float)$r['subtotal'],2)?></td><td><span class="badge-df <?=e(eb((string)$r['fulfillment_status']))?>"><?=e(ucfirst($r['fulfillment_status']))?></span></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4"><div class="empty-df">No seller sales recorded yet.</div></td></tr><?php endif;?></tbody></table></div></section>
